FunctionInfo currentFunction = null;
// symbol table: varName -> type (e.g. "int", "float")
Map<String, String> symbolTable = new HashMap<String,String>();
class Sym {
    String name;
    String type;
    int line;
    boolean used = false;

    Sym(String name, String type, int line) {
        this.name = name;
        this.type = type;
        this.line = line;
    }
}

Deque<Map<String, Sym>> scopes = new ArrayDeque<>();

// init global scope
{
    scopes.push(new HashMap<>());
}

// enter/exit scope
void enterScope() {
    scopes.push(new HashMap<>());
}

void exitScope() {
    Map<String, Sym> scope = scopes.pop();
    for (Sym s : scope.values()) {
        if (!s.used) {
            System.out.println("[Warning] variable '" + s.name +
                "' declared at line " + s.line + " but never used.");
        }
    }
}

// declare variable
Map<String, FunctionInfo> functionTable = new HashMap<>();

void declareVar(String name, String type, int line) {
    Map<String, Sym> cur = scopes.peek();
    if (cur.containsKey(name)) {
        System.out.println("[Error] Redeclaration of '" + name +
            "' at line " + line);
    } else {
        // shadowing?
        for (Map<String, Sym> sc : scopes) {
            if (sc != cur && sc.containsKey(name)) {
                System.out.println("[Warning] Shadowing variable '" +
                    name + "' at line " + line);
                break;
            }
        }
        cur.put(name, new Sym(name, type, line));
    }
}

// lookup
Sym lookup(String name) {
    for (Map<String, Sym> sc : scopes) {
        if (sc.containsKey(name)) return sc.get(name);
    }
    return null;
}

// mark usage
void useVar(String name, int line) {
    Sym s = lookup(name);
    if (s == null) {
        System.out.println("[Error] variable '" + name +
            "' used before declaration at line " + line);  // استفاده از پارامتر line
    } else {
        s.used = true;
    }
}
// var values (numeric): varName -> Number value (if initialized)
Map<String, Number> varValues = new HashMap<String,Number>();
boolean isNumericType(ArithmeticResult ar) {
    if (ar == null) return false;
    if (ar.isVariable()) {
        Sym sym = lookup(ar.getVarName());
        if (sym != null) {
            return sym.type.equals("int") || sym.type.equals("float") ||
                   sym.type.equals("double") || sym.type.equals("long") ||
                   sym.type.equals("short") || sym.type.equals("byte");
        }
        return false;
    } else {
        return ar.value instanceof Number;
    }
}

String getTypeName(ArithmeticResult ar) {
    if (ar == null) return "unknown";
    if (ar.isVariable()) {
        Sym sym = lookup(ar.getVarName());
        return (sym != null) ? sym.type : "unknown";
    } else {
        if (ar.value instanceof Integer) return "int";
        if (ar.value instanceof Float) return "float";
        if (ar.value instanceof Double) return "double";
        if (ar.value instanceof Long) return "long";
        return "unknown";
    }
}
// helper to format an argument for printing in funcall
private String formatArg(Object arg) {
    if (arg == null) return "null";
    if (arg instanceof ArithmeticResult) {
        ArithmeticResult ar = (ArithmeticResult) arg;
        if (ar.varName != null) {
            String type = symbolTable.get(ar.varName);
            if (type == null) type = "unknown";
            return type + " " + ar.varName;
        } else if (ar.value != null) {
            return ar.value.toString();
        } else {
            return (ar.operation != null) ? ar.operation : "expr";
        }
    } else if (arg instanceof String) {
        String name = (String) arg;
        String type = symbolTable.get(name);
        if (type == null) type = "unknown";
        return type + " " + name;
    } else {
        return arg.toString();
    }
}


private Number addNumbers(Number a, Number b) {
    if (a instanceof Double || b instanceof Double) {
        return Double.valueOf(a.doubleValue() + b.doubleValue());
    } else if (a instanceof Float || b instanceof Float) {
        return Float.valueOf(a.floatValue() + b.floatValue());
    } else if (a instanceof Long || b instanceof Long) {
        return Long.valueOf(a.longValue() + b.longValue());
    } else {
        return Integer.valueOf(a.intValue() + b.intValue());
    }
}

private Number subNumbers(Number a, Number b) {
    if (a instanceof Double || b instanceof Double) {
        return Double.valueOf(a.doubleValue() - b.doubleValue());
    } else if (a instanceof Float || b instanceof Float) {
        return Float.valueOf(a.floatValue() - b.floatValue());
    } else if (a instanceof Long || b instanceof Long) {
        return Long.valueOf(a.longValue() - b.longValue());
    } else {
        return Integer.valueOf(a.intValue() - b.intValue());
    }
}

private Number mulNumbers(Number a, Number b) {
    if (a instanceof Double || b instanceof Double) {
        return Double.valueOf(a.doubleValue() * b.doubleValue());
    } else if (a instanceof Float || b instanceof Float) {
        return Float.valueOf(a.floatValue() * b.floatValue());
    } else if (a instanceof Long || b instanceof Long) {
        return Long.valueOf(a.longValue() * b.longValue());
    } else {
        return Integer.valueOf(a.intValue() * b.intValue());
    }
}

private Number divNumbers(Number a, Number b) {
    if (a.doubleValue() == 0.0) {
        throw new ArithmeticException("Division by zero");
    }
    if (a instanceof Double || b instanceof Double) {
        return Double.valueOf(a.doubleValue() / b.doubleValue());
    } else if (a instanceof Float || b instanceof Float) {
        return Float.valueOf(a.floatValue() / b.floatValue());
    } else if (a instanceof Long || b instanceof Long) {
        return Long.valueOf(a.longValue() / b.longValue());
    } else {
        return Integer.valueOf(a.intValue() / b.intValue());
    }
}
String getArgumentType(Object arg) {
    if (arg instanceof ArithmeticResult) {
        ArithmeticResult ar = (ArithmeticResult) arg;
        return getTypeName(ar);
    } else if (arg instanceof String) {
        Sym sym = lookup((String) arg);
        return (sym != null) ? sym.type : "unknown";
    }
    return "unknown";
}
private Number modNumbers(Number a, Number b) {
    if (a instanceof Double || b instanceof Double) {
        return Double.valueOf(a.doubleValue() % b.doubleValue());
    } else if (a instanceof Float || b instanceof Float) {
        return Float.valueOf(a.floatValue() % b.floatValue());
    } else if (a instanceof Long || b instanceof Long) {
        return Long.valueOf(a.longValue() % b.longValue());
    } else {
        return Integer.valueOf(a.intValue() % b.intValue());
    }
}
String getExpressionType(Object exp) {
    if (exp instanceof ArithmeticResult) {
        ArithmeticResult ar = (ArithmeticResult) exp;
        return getTypeName(ar);
    }
    return null;
}
Number convertType(Number value, String targetType) {
    if (targetType.equals("int")) return value.intValue();
    if (targetType.equals("float")) return value.floatValue();
    if (targetType.equals("double")) return value.doubleValue();
    if (targetType.equals("long")) return value.longValue();
    return value;
}

boolean canConvertImplicitly(String fromType, String toType) {
    // تبدیل‌های مجاز: int → float → double
    if (fromType.equals("int") && toType.equals("float")) return true;
    if (fromType.equals("int") && toType.equals("double")) return true;
    if (fromType.equals("float") && toType.equals("double")) return true;
    if (fromType.equals(toType)) return true;
    return false;
}
