   class FunctionInfo {
    String returnType;
    String name;
    java.util.List<ParameterInfo> parameters;

    public FunctionInfo(String returnType, String name, java.util.List<ParameterInfo> parameters) {
        this.returnType = returnType;
        this.name = name;
        this.parameters = parameters;
    }


@Override
public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append("Function: ").append(name)
      .append(", Return type: ").append(returnType)
      .append(", Parameters: ");
    if (parameters != null && !parameters.isEmpty()) {
        for (ParameterInfo p : parameters) {
            sb.append(p.toString()).append(", ");
        }
        sb.setLength(sb.length() - 2);
    } else {
        sb.append("none");
    }
    return sb.toString();
}

}
